const testCases = $('Test Cases').all();
const sageOutputs = $input.all();

const results = sageOutputs.map((item, i) => {
  const text = item.json.output?.[0]?.content?.[0]?.text ?? "";

  // Same safe parsing as Parse SAGE JSON: keep the part between the first "{" and last "}"
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");
  let actualIntent = null;
  try {
    actualIntent = JSON.parse(text.slice(start, end + 1)).intent ?? null;
  } catch (err) {
    actualIntent = "PARSE_ERROR";
  }

  const expected = testCases[i].json.expected_intent;
  return {
    message: testCases[i].json.message,
    expected,
    actual: actualIntent,
    correct: actualIntent === expected
  };
});

const correctCount = results.filter(r => r.correct).length;

return [{
  json: {
    accuracy: `${correctCount}/${results.length} (${Math.round(correctCount / results.length * 100)}%)`,
    misses: results.filter(r => !r.correct),
    all_results: results
  }
}];

// Each case: a customer message and the intent we EXPECT SAGE to return
const testCases = [
  // refund_request
  { message: "My blender arrived with a cracked jar. I want my money back.", expected_intent: "refund_request" },
  { message: "Bhai headphones ka ek side kaam nahi karta, refund chahiye.", expected_intent: "refund_request" },
  { message: "The product is nothing like the description. Please refund my ₹2,499.", expected_intent: "refund_request" },

  // cancellation_request
  { message: "I placed an order an hour ago by mistake, please cancel it.", expected_intent: "cancellation_request" },
  { message: "Cancel my order ORD-5521, I don't need it anymore.", expected_intent: "cancellation_request" },

  // delivery_issue
  { message: "My order was supposed to arrive last Monday and it still hasn't come.", expected_intent: "delivery_issue" },
  { message: "Tracking says delivered but there's no package at my door.", expected_intent: "delivery_issue" },
  { message: "Courier wala 3 din se aa hi nahi raha, mera order kahan hai?", expected_intent: "delivery_issue" },

  // return_request
  { message: "The shoes don't fit. How do I return them?", expected_intent: "return_request" },
  { message: "I'd like to return the jacket I bought, the colour looks different in person.", expected_intent: "return_request" },

  // replacement_request
  { message: "The phone case I received is the wrong model. Can you send the correct one instead?", expected_intent: "replacement_request" },
  { message: "My kettle arrived dented. I'd like a replacement, not a refund.", expected_intent: "replacement_request" },

  // technical_support
  { message: "My smartwatch won't pair with my phone over Bluetooth. How do I fix it?", expected_intent: "technical_support" },
  { message: "The app keeps logging me out every time I open it.", expected_intent: "technical_support" },

  // general_question
  { message: "Do you ship to Pune?", expected_intent: "general_question" },
  { message: "What payment methods do you accept?", expected_intent: "general_question" },
  { message: "Do you offer gift wrapping?", expected_intent: "general_question" },

  // unrelated
  { message: "Can you recommend a good movie for tonight?", expected_intent: "unrelated" },
  { message: "What's the capital of Australia?", expected_intent: "unrelated" },

  // other
  { message: "Great service last time, just wanted to say thanks!", expected_intent: "other" },

  // HELD-OUT: written after the prompt change, using none of the prompt's example words
  { message: "Is there an EMI option on laptops above ₹50,000?", expected_intent: "general_question" },
  { message: "Do you have the new Sony noise-cancelling headphones in stock?", expected_intent: "general_question" },
  { message: "Aapka koi physical store hai Mumbai mein?", expected_intent: "general_question" },
  { message: "Your website looks really clean after the redesign, nice work.", expected_intent: "other" },
  { message: "Who won the cricket match yesterday?", expected_intent: "unrelated" },
  { message: "How long does the warranty last on your headphones?", expected_intent: "general_question" }
];

// n8n expects a list of items, each wrapped in { json: ... }
return testCases.map(testCase => ({ json: testCase }));
